X, Y = np.meshgrid(x_freqs, y_wg_widths)
mask = (mode2 == 0)
        


def main():

    if plot_total_power:
        fig = plt.figure()
        ax = fig.add_subplot(111, projection='3d')

        ax.plot_surface(X, Y, total_power, cmap='viridis')

        ax.set_xlabel('Frequency')
        ax.set_ylabel('Waveguide Width')
        ax.set_zlabel('Efficiency')
        plt.title("Grating Coupler N_WG=3.47 Total Power")


    if plot_mode_0:
        fig = plt.figure()
        ax = fig.add_subplot(111, projection='3d')

        ax.plot_surface(X, Y, mode0, cmap='viridis')

        ax.set_xlabel('Frequency')
        ax.set_ylabel('Waveguide Width')
        ax.set_zlabel('Efficiency')
        plt.title("Grating Coupler N_WG=3.47 Fundamental Mode")


    if plot_mode_1:
        fig = plt.figure()
        ax = fig.add_subplot(111, projection='3d')

        ax.plot_surface(X, Y, mode1, cmap='viridis')

        ax.set_xlabel('Frequency')
        ax.set_ylabel('Waveguide Width')
        ax.set_zlabel('Efficiency')
        plt.title("Grating Coupler N_WG=3.47 First Mode")


    if plot_mode_2:
        fig = plt.figure()
        ax = fig.add_subplot(111, projection='3d')

        ax.plot_surface(X, Y, mode2, cmap='viridis')

        ax.set_xlabel('Frequency')
        ax.set_ylabel('Waveguide Width')
        ax.set_zlabel('Efficiency')
        plt.title("Grating Coupler N_WG=3.47 Second Mode")


    if plot_valid_power:
        valid_power = np.where(mask, total_power, 0)
        max_pos = np.unravel_index(np.argmax(valid_power), valid_power.shape)

        print("Max Valid Total Power Efficiency with: \nFREQUENCY = ", f_min+max_pos[1]*f_res, 
              " AND WG WIDTH = ", wgw_min + max_pos[0]*wgw_res, 
              "\nEFFICIENCY of ", total_power[max_pos])


        fig = plt.figure()
        ax = fig.add_subplot(111, projection='3d')

        ax.plot_surface(X, Y, valid_power, cmap='viridis')

        ax.set_xlabel('Frequency')
        ax.set_ylabel('Waveguide Width')
        ax.set_zlabel('Efficiency')
        plt.title("Grating Coupler N_WG=3.47 Valid Total Power")


    if optimize_mode_0:
        valid_mode0 = np.where(mask, mode0, 0)
        max_pos = np.unravel_index(np.argmax(valid_mode0), valid_mode0.shape)

        print("Max Valid Mode 0 Efficiency with: \nFREQUENCY = ", f_min+max_pos[1]*f_res, 
                " AND WG WIDTH = ", wgw_min + max_pos[0]*wgw_res, 
                "\nEFFICIENCY of ", total_power[max_pos])


        fig = plt.figure()
        ax = fig.add_subplot(111, projection='3d')

        ax.plot_surface(X, Y, valid_mode0, cmap='viridis')

        ax.set_xlabel('Frequency')
        ax.set_ylabel('Waveguide Width')
        ax.set_zlabel('Efficiency')
        plt.title("Grating Coupler N_WG=3.47 Valid Fundamental Mode Power")


    if optimize_mode_1:
        valid_mode1 = np.where(mask, mode1, 0)
        max_pos = np.unravel_index(np.argmax(valid_mode1), valid_mode1.shape)

        print("Max Valid Mode 1 Efficiency with: \nFREQUENCY = ", f_min+max_pos[1]*f_res, 
                " AND WG WIDTH = ", wgw_min + max_pos[0]*wgw_res, 
                "\nEFFICIENCY of ", total_power[max_pos])


        fig = plt.figure()
        ax = fig.add_subplot(111, projection='3d')

        ax.plot_surface(X, Y, valid_mode1, cmap='viridis')

        ax.set_xlabel('Frequency')
        ax.set_ylabel('Waveguide Width')
        ax.set_zlabel('Efficiency')
        plt.title("Grating Coupler N_WG=3.47 Valid First Mode Power")



    plt.show()


if __name__ == "__main__":
    main()

    mode1_stoch = total_power - mode0

    fig = plt.figure()
    ax = fig.add_subplot(111, projection='3d')

    ax.plot_surface(X, Y, mode1_stoch, cmap='viridis')

    ax.set_xlabel('Frequency')
    ax.set_ylabel('Waveguide Width')
    ax.set_zlabel('Efficiency')
    plt.title("Grating Coupler N_WG=3.47 Fundamental Mode")

    plt.show()